from pathlib import Path
from html import escape
import json,shutil,argparse,re,hashlib
ROOT=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--config',type=Path,default=ROOT/'src/config.json');p.add_argument('--out',type=Path,default=ROOT/'dist');args=p.parse_args()
c=json.loads(args.config.read_text());out=args.out;out.mkdir(parents=True,exist_ok=True)
active=c['signupEnabled']
if c['policiesApproved'] and not (ROOT/'src/approved-retention.html').exists():
 raise SystemExit('Launch blocked: add src/approved-retention.html with the approved retention policy.')
if active and any(str(c[k]).startswith('draft') for k in ['consentVersion','termsVersion','privacyVersion']):
 raise SystemExit('Launch blocked: replace draft version identifiers with approved version identifiers.')
