mark='<svg viewBox="0 0 141 95" aria-hidden="true" fill="currentColor"><path d="M0 95 19 37H66L47 95ZM57 95 88 0H141L110 95Z"/></svg>'
def header():return '''<a class="skip" href="#main">Skip to content</a><div class="notice">Life beyond surgery. <b>Always forward.</b></div><header class="header"><nav class="nav" aria-label="Main navigation"><a class="logo" href="/" aria-label="Eleven Forward home"><img src="/assets/logo-dark.png" width="580" height="96" alt="Eleven Forward"></a><button class="menu" type="button" aria-expanded="false" aria-controls="nav-links">Menu +</button><div class="nav-links" id="nav-links"><a href="/#p001">P001</a><a href="/#our-story">Our story</a><a href="/#survival-club">Survival Club</a><a class="nav-cta" href="/#updates" data-interest="p001">Get updates <span class="arrow" aria-hidden="true">↗</span></a></div></nav></header>'''
def footer():
 contactlink=f'<a href="mailto:{e(contact)}">Contact</a>' if contact else ''
 return f'''<footer class="footer"><div class="footer-top"><a class="logo" href="/" aria-label="Eleven Forward home"><img src="/assets/logo-light.png" width="580" height="96" alt="Eleven Forward" loading="lazy"></a><div class="footer-links"><a href="/terms/">Terms of Service</a><a href="/privacy/">Privacy Policy</a>{contactlink}</div></div><div class="footer-bottom"><p>© 2026 Eleven Forward</p></div></footer>'''
asset_names={name:f"{Path(name).stem}.{hashlib.sha256((ROOT/'src'/name).read_bytes()).hexdigest()[:12]}{Path(name).suffix}" for name in ['styles.css','app.js']}
def document(title,desc,body,path='/',noindex=False):
 index='noindex, nofollow' if noindex or not active else 'index, follow'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(desc)}"><meta name="robots" content="{index}"><meta name="theme-color" content="#F5F5F0"><link rel="canonical" href="{e(url+path)}"><meta property="og:type" content="website"><meta property="og:site_name" content="Eleven Forward"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{e(url+path)}"><meta property="og:image" content="{e(url)}/assets/social-preview.jpg"><meta property="og:image:alt" content="Eleven Forward P001 sport band concept"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/Inter-Regular.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="/assets/{asset_names['styles.css']}"><script type="module" src="/assets/{asset_names['app.js']}"></script></head><body>{header()}{body}{footer()}</body></html>'''
def write(path,content):
 target=out/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(content)
def picture(name,widths,width,height,alt,eager=False):
 return f'''<picture><source type="image/webp" srcset="{', '.join(f'/assets/{name}-{w}.webp {min(w,width)}w' for w in widths)}" sizes="{'(max-width: 640px) 100vw, 82vw' if name=='product' else '100vw' if name in ['shirt','shirt-white','hat'] else '(max-width: 640px) 191px, 280px'}"><img src="/assets/{name}.jpg" width="{width}" height="{height}" alt="{e(alt)}" {'fetchpriority="high"' if eager else 'loading="lazy"'} decoding="async"></picture>'''
